/usr/bin/bash -lc "perl -MIO::Uncompress::Gunzip=gunzip -e '
use strict; use warnings;
my ("'$f,$r)=@ARGV;
my $F=IO::Uncompress::Gunzip->new($f) or die $IO::Uncompress::Gunzip::GunzipError;
my $R=IO::Uncompress::Gunzip->new($r) or die $IO::Uncompress::Gunzip::GunzipError;
my ($pairs,$id_bad,$format_bad,$min_f,$min_r,$max_nf,$max_nr,$max_lqf,$max_lqr)=(0,0,0,10**9,10**9,0,0,0,0);
while (1) {
  my @a=map { scalar <$F> } 1..4; my @b=map { scalar <$R> } 1..4;
  last if !defined($a[0]) && !defined($b[0]);
  die "mate count mismatch'"\\n\" if "'!defined($a[0]) || !defined($b[0]);
  $pairs++;
  chomp @a; chomp @b;
  my ($ida)=split /'"\\s+/, "'$a[0]; my ($idb)=split /'"\\s+/, "'$b[0];
  $id_bad++ if $ida ne $idb;
  $format_bad++ if substr($a[0],0,1) ne q{@} || substr($b[0],0,1) ne q{@} || substr($a[2],0,1) ne q{+} || substr($b[2],0,1) ne q{+} || length($a[1]) != length($a[3]) || length($b[1]) != length($b[3]);
  my ($lf,$lr)=(length($a[1]),length($b[1])); $min_f=$lf if $lf<$min_f; $min_r=$lr if $lr<$min_r;
  my $nf=($a[1]=~tr/Nn//); my $nr=($b[1]=~tr/Nn//); $max_nf=$nf if $nf>$max_nf; $max_nr=$nr if $nr>$max_nr;
  my $qf=grep { (ord($_)-33)<20 } split //,$a[3]; my $qr=grep { (ord($_)-33)<20 } split //,$b[3];
  my $pf=$lf ? $qf/$lf : 1; my $pr=$lr ? $qr/$lr : 1; $max_lqf=$pf if $pf>$max_lqf; $max_lqr=$pr if $pr>$max_lqr;
  die "retained read violates filter at pair $pairs'"\\n\" if "'$lf<15 || $lr<15 || $nf>5 || $nr>5 || $pf>0.4+1e-12 || $pr>0.4+1e-12;
}
print "pairs=$pairs'"\\nid_mismatches="'$id_bad'"\\nformat_errors="'$format_bad'"\\nmin_lengths="'$min_f,$min_r'"\\nmax_N_counts="'$max_nf,$max_nr'"\\nmax_low_quality_fractions=\",sprintf(\"%.6f,%.6f\","'$max_lqf,$max_lqr),"'"\\n\";
' final_answer/trimmed_forward.fastqsanger.gz final_answer/trimmed_reverse.fastqsanger.gz"

